-- Script d'insertion pour la table agences
-- Généré le 2025-10-28
-- Total: 104 agences du Togo

-- Nettoyage préalable (optionnel - décommenter si nécessaire)
-- TRUNCATE TABLE agences RESTART IDENTITY CASCADE;

-- Insertions des agences avec leurs codes

-- Vérification du nombre d'agences insérées
SELECT COUNT(*) AS total_agences FROM agences;

-- Afficher les agences par région
SELECT region, COUNT(*) AS nombre 
FROM agences 
GROUP BY region 
ORDER BY nombre DESC;
